        while (!inFile.eof()) {
            IsDelimiter = (c == ' ' || c == 10 || c == 13 || c == ',' || c == '.' || c == '\'' ||
                           c == ':' || c == ';' || c == '"' || c == '?' || c == '!' || c == '-' ||
                           c == '(' || c == ')' || c == '[' || c == ']' || c == '_' || c == '*' || c == 9);
